400		 * Base class for adapters that adapt a bean to a {@link GenericConverter}.
401		 *
402		 * @param <B> the base type of the bean
403		 */
404		abstract static class BeanAdapter<B> implements ConditionalGenericConverter {
405	
406			private final B bean;
407	
408			private final ResolvableTypePair types;
409	
410			BeanAdapter(B bean, ResolvableType beanType) {
411				Assert.isInstanceOf(beanType.toClass(), bean);
412				ResolvableType type = ResolvableType.forClass(getClass()).as(BeanAdapter.class).getGeneric();
413				ResolvableType[] generics = beanType.as(type.toClass()).getGenerics();
414				this.bean = bean;
415				this.types = getResolvableTypePair(generics);
416			}
417	
418			protected ResolvableTypePair getResolvableTypePair(ResolvableType[] generics) {
419				return new ResolvableTypePair(generics[0], generics[1]);
420			}
421	
422			protected B bean() {
423				return this.bean;
424			}
425	
426			@Override
427			public Set<ConvertiblePair> getConvertibleTypes() {
428				return Set.of(new ConvertiblePair(this.types.source().toClass(), this.types.target().toClass()));
429			}
430	
431			@Override
432			public boolean matches(TypeDescriptor sourceType, TypeDescriptor targetType) {
433				return (this.types.target().toClass() == targetType.getObjectType()
434						&& matchesTargetType(targetType.getResolvableType()));
435			}
436	
437			private boolean matchesTargetType(ResolvableType targetType) {
438				ResolvableType ours = this.types.target();
439				return targetType.getType() instanceof Class || targetType.isAssignableFrom(ours)
440						|| this.types.target().hasUnresolvableGenerics();
441			}
442	
443			protected final boolean conditionalConverterCandidateMatches(Object conditionalConverterCandidate,
444					TypeDescriptor sourceType, TypeDescriptor targetType) {
445				return (conditionalConverterCandidate instanceof ConditionalConverter conditionalConverter)
446						? conditionalConverter.matches(sourceType, targetType) : true;
447			}
448	
449			@SuppressWarnings({ "unchecked", "rawtypes" })
450			protected final @Nullable Object convert(@Nullable Object source, TypeDescriptor targetType,
451					Converter<?, ?> converter) {
452				return (source != null) ? ((Converter) converter).convert(source) : convertNull(targetType);
453			}
454	
455			private @Nullable Object convertNull(TypeDescriptor targetType) {
456				return (targetType.getObjectType() != Optional.class) ? null : Optional.empty();
457			}
458	
459			@Override
460			public String toString() {
461				return this.types + " : " + this.bean;
462			}
463	
464		}
465	
466		/**
467		 * Adapts a {@link Printer} bean to a {@link GenericConverter}.
468		 */
469		static class PrinterBeanAdapter extends BeanAdapter<Printer<?>> {
470	
471			PrinterBeanAdapter(Printer<?> bean, ResolvableType beanType) {
472				super(bean, beanType);
473			}
474	
475			@Override
476			protected ResolvableTypePair getResolvableTypePair(ResolvableType[] generics) {
477				return new ResolvableTypePair(generics[0], STRING);
478			}
479	
480			@Override
481			public Object convert(@Nullable Object source, TypeDescriptor sourceType, TypeDescriptor targetType) {
482				return (source != null) ? print(source) : "";
483			}
484	
485			@SuppressWarnings("unchecked")
486			private String print(Object object) {
487				return ((Printer<Object>) bean()).print(object, LocaleContextHolder.getLocale());
488			}
489	
490		}
491	
492		/**
493		 * Adapts a {@link Parser} bean to a {@link GenericConverter}.
494		 */
495		static class ParserBeanAdapter extends BeanAdapter<Parser<?>> {
496	
497			ParserBeanAdapter(Parser<?> bean, ResolvableType beanType) {
498				super(bean, beanType);
499			}
500	
501			@Override
502			protected ResolvableTypePair getResolvableTypePair(ResolvableType[] generics) {
503				return new ResolvableTypePair(STRING, generics[0]);
504			}
505	
506			@Override
507			public @Nullable Object convert(@Nullable Object source, TypeDescriptor sourceType, TypeDescriptor targetType) {
508				String text = (String) source;
509				return (!StringUtils.hasText(text)) ? null : parse(text);
510			}
511	
512			private Object parse(String text) {
513				try {
514					return bean().parse(text, LocaleContextHolder.getLocale());
515				}
516				catch (IllegalArgumentException ex) {
517					throw ex;
518				}
519				catch (Throwable ex) {
520					throw new IllegalArgumentException("Parse attempt failed for value [" + text + "]", ex);
521				}
522			}
523	
524		}
525	
526		/**
527		 * Adapts a {@link Converter} bean to a {@link GenericConverter}.
528		 */
529		static final class ConverterBeanAdapter extends BeanAdapter<Converter<?, ?>> {
530	
531			ConverterBeanAdapter(Converter<?, ?> bean, ResolvableType beanType) {
532				super(bean, beanType);
533			}
534	
535			@Override
536			public boolean matches(TypeDescriptor sourceType, TypeDescriptor targetType) {
537				return super.matches(sourceType, targetType)
538						&& conditionalConverterCandidateMatches(bean(), sourceType, targetType);
539			}
540	
541			@Override
542			public @Nullable Object convert(@Nullable Object source, TypeDescriptor sourceType, TypeDescriptor targetType) {
543				return convert(source, targetType, bean());
544			}
545	
546		}
547	
548		/**
549		 * Adapts a {@link ConverterFactory} bean to a {@link GenericConverter}.
550		 */
551		private static final class ConverterFactoryBeanAdapter extends BeanAdapter<ConverterFactory<?, ?>> {
552	
553			ConverterFactoryBeanAdapter(ConverterFactory<?, ?> bean, ResolvableType beanType) {
554				super(bean, beanType);
555			}
556	
557			@Override
558			public boolean matches(TypeDescriptor sourceType, TypeDescriptor targetType) {
559				return super.matches(sourceType, targetType)
560						&& conditionalConverterCandidateMatches(bean(), sourceType, targetType)
561						&& conditionalConverterCandidateMatches(getConverter(targetType::getType), sourceType, targetType);
562			}
563	
564			@Override
565			public @Nullable Object convert(@Nullable Object source, TypeDescriptor sourceType, TypeDescriptor targetType) {
566				return convert(source, targetType, getConverter(targetType::getObjectType));
567			}
568	
569			@SuppressWarnings({ "unchecked", "rawtypes" })
570			private Converter<Object, ?> getConverter(Supplier<Class<?>> typeSupplier) {
571				return ((ConverterFactory) bean()).getConverter(typeSupplier.get());
572			}
573	
574		}
575	
576		/**
577		 * Convertible type information as extracted from bean generics.
578		 *
579		 * @param source the source type
580		 * @param target the target type
581		 */
582		record ResolvableTypePair(ResolvableType source, ResolvableType target) {
583	
584			ResolvableTypePair {
585				Assert.notNull(source.resolve(), "'source' cannot be resolved");
586				Assert.notNull(target.resolve(), "'target' cannot be resolved");
587			}
588	
589			@Override
590			public final String toString() {
591				return source() + " -> " + target();
592			}
593	
594		}
595	
596	}
