47	/**
48	 * Banner implementation that prints from a source text {@link Resource}.
49	 *
50	 * @author Phillip Webb
51	 * @author Vedran Pavic
52	 * @author Toshiaki Maki
53	 * @author Krzysztof Krason
54	 * @author Moritz Halbritter
55	 * @since 1.2.0
56	 */
57	public class ResourceBanner implements Banner {
58	
59		private static final Log logger = LogFactory.getLog(ResourceBanner.class);
60	
61		private final Resource resource;
62	
63		public ResourceBanner(Resource resource) {
64			Assert.notNull(resource, "'resource' must not be null");
65			Assert.isTrue(resource.exists(), "'resource' must exist");
66			this.resource = resource;
67		}
68	
69		@Override
70		public void printBanner(Environment environment, @Nullable Class<?> sourceClass, PrintStream out) {
71			try (InputStream input = this.resource.getInputStream()) {
72				String banner = StreamUtils.copyToString(input,
73						environment.getProperty("spring.banner.charset", Charset.class, StandardCharsets.UTF_8));
74				for (PropertyResolver resolver : getPropertyResolvers(environment, sourceClass)) {
75					banner = resolver.resolvePlaceholders(banner);
76				}
77				out.println(banner);
78			}
79			catch (Exception ex) {
80				logger.warn(LogMessage.format("Banner not printable: %s (%s: '%s')", this.resource, ex.getClass(),
81						ex.getMessage()), ex);
82			}
83		}
84	
85		/**
86		 * Return a mutable list of the {@link PropertyResolver} instances that will be used
87		 * to resolve placeholders.
88		 * @param environment the environment
89		 * @param sourceClass the source class
90		 * @return a mutable list of property resolvers
91		 */
92		protected List<PropertyResolver> getPropertyResolvers(Environment environment, @Nullable Class<?> sourceClass) {
93			List<PropertyResolver> resolvers = new ArrayList<>();
94			resolvers.add(new PropertySourcesPropertyResolver(createNullDefaultSources(environment, sourceClass)));
95			resolvers.add(new PropertySourcesPropertyResolver(createEmptyDefaultSources(environment, sourceClass)));
96			return resolvers;
97		}
98	
99		private MutablePropertySources createNullDefaultSources(Environment environment, @Nullable Class<?> sourceClass) {
100			MutablePropertySources nullDefaultSources = new MutablePropertySources();
101			if (environment instanceof ConfigurableEnvironment configurableEnvironment) {
102				configurableEnvironment.getPropertySources().forEach(nullDefaultSources::addLast);
103			}
104			nullDefaultSources.addLast(getTitleSource(sourceClass, null));
105			nullDefaultSources.addLast(getAnsiSource());
106			nullDefaultSources.addLast(getVersionSource(environment, null));
107			return nullDefaultSources;
108		}
109	
110		private MutablePropertySources createEmptyDefaultSources(Environment environment, @Nullable Class<?> sourceClass) {
111			MutablePropertySources emptyDefaultSources = new MutablePropertySources();
112			emptyDefaultSources.addLast(getTitleSource(sourceClass, ""));
113			emptyDefaultSources.addLast(getVersionSource(environment, ""));
114			return emptyDefaultSources;
115		}
116	
117		private MapWithNullsPropertySource getTitleSource(@Nullable Class<?> sourceClass, @Nullable String defaultValue) {
118			String applicationTitle = getApplicationTitle(sourceClass);
119			Map<String, @Nullable Object> titleMap = Collections.singletonMap("application.title",
120					(applicationTitle != null) ? applicationTitle : defaultValue);
121			return new MapWithNullsPropertySource("title", titleMap);
122		}
123	
124		/**
125		 * Return the application title that should be used for the source class. By default
126		 * will use {@link Package#getImplementationTitle()}.
127		 * @param sourceClass the source class
128		 * @return the application title
129		 */
130		protected @Nullable String getApplicationTitle(@Nullable Class<?> sourceClass) {
131			Package sourcePackage = (sourceClass != null) ? sourceClass.getPackage() : null;
132			return (sourcePackage != null) ? sourcePackage.getImplementationTitle() : null;
133		}
134	
135		private AnsiPropertySource getAnsiSource() {
136			return new AnsiPropertySource("ansi", true);
137		}
138	
139		private MapWithNullsPropertySource getVersionSource(Environment environment, @Nullable String defaultValue) {
140			return new MapWithNullsPropertySource("version", getVersionsMap(environment, defaultValue));
141		}
142	
143		private Map<String, @Nullable Object> getVersionsMap(Environment environment, @Nullable String defaultValue) {
144			String appVersion = getApplicationVersion(environment);
145			String bootVersion = getBootVersion();
146			Map<String, @Nullable Object> versions = new HashMap<>();
147			versions.put("application.version", getVersionString(appVersion, false, defaultValue));
148			versions.put("spring-boot.version", getVersionString(bootVersion, false, defaultValue));
149			versions.put("application.formatted-version", getVersionString(appVersion, true, defaultValue));
150			versions.put("spring-boot.formatted-version", getVersionString(bootVersion, true, defaultValue));
151			return versions;
152		}
153	
154		private @Nullable String getApplicationVersion(Environment environment) {
155			return environment.getProperty("spring.application.version");
156		}
157	
158		protected @Nullable String getBootVersion() {
159			return SpringBootVersion.getVersion();
160		}
161	
162		private @Nullable String getVersionString(@Nullable String version, boolean format, @Nullable String fallback) {
163			if (version == null) {
164				return fallback;
165			}
166			return format ? " (v" + version + ")" : version;
167		}
168	
169		/**
170		 * Like {@link MapPropertySource}, but allows {@code null} as map values.
171		 */
