127		@Override
128		public ConditionOutcome getMatchOutcome(ConditionContext context, AnnotatedTypeMetadata metadata) {
129			ConditionOutcome matchOutcome = ConditionOutcome.match();
130			MergedAnnotations annotations = metadata.getAnnotations();
131			if (annotations.isPresent(ConditionalOnBean.class)) {
132				Spec<ConditionalOnBean> spec = new Spec<>(context, metadata, annotations, ConditionalOnBean.class);
133				matchOutcome = evaluateConditionalOnBean(spec, matchOutcome.getConditionMessage());
134				if (!matchOutcome.isMatch()) {
135					return matchOutcome;
136				}
137			}
138			if (metadata.isAnnotated(ConditionalOnSingleCandidate.class.getName())) {
139				Spec<ConditionalOnSingleCandidate> spec = new SingleCandidateSpec(context, metadata,
140						metadata.getAnnotations());
141				matchOutcome = evaluateConditionalOnSingleCandidate(spec, matchOutcome.getConditionMessage());
142				if (!matchOutcome.isMatch()) {
143					return matchOutcome;
144				}
145			}
146			if (metadata.isAnnotated(ConditionalOnMissingBean.class.getName())) {
147				Spec<ConditionalOnMissingBean> spec = new Spec<>(context, metadata, annotations,
148						ConditionalOnMissingBean.class);
149				matchOutcome = evaluateConditionalOnMissingBean(spec, matchOutcome.getConditionMessage());
150				if (!matchOutcome.isMatch()) {
151					return matchOutcome;
152				}
153			}
154			return matchOutcome;
155		}
