157		private ConditionOutcome evaluateConditionalOnBean(Spec<ConditionalOnBean> spec, ConditionMessage matchMessage) {
158			MatchResult matchResult = getMatchingBeans(spec);
159			if (!matchResult.isAllMatched()) {
160				String reason = createOnBeanNoMatchReason(matchResult);
161				return ConditionOutcome.noMatch(spec.message().because(reason));
162			}
163			return ConditionOutcome.match(spec.message(matchMessage)
164				.found("bean", "beans")
165				.items(Style.QUOTE, matchResult.getNamesOfAllMatches()));
166		}
167	
168		private ConditionOutcome evaluateConditionalOnSingleCandidate(Spec<ConditionalOnSingleCandidate> spec,
169				ConditionMessage matchMessage) {
170			MatchResult matchResult = getMatchingBeans(spec);
171			if (!matchResult.isAllMatched()) {
172				return ConditionOutcome.noMatch(spec.message().didNotFind("any beans").atAll());
173			}
174			Set<String> allBeans = matchResult.getNamesOfAllMatches();
175			if (allBeans.size() == 1) {
176				return ConditionOutcome
177					.match(spec.message(matchMessage).found("a single bean").items(Style.QUOTE, allBeans));
178			}
179			ConfigurableListableBeanFactory beanFactory = spec.context.getBeanFactory();
180			Assert.state(beanFactory != null, "'beanFactory' must not be null");
181			Map<String, @Nullable BeanDefinition> beanDefinitions = getBeanDefinitions(beanFactory, allBeans,
182					spec.getStrategy() == SearchStrategy.ALL);
183			List<String> primaryBeans = getPrimaryBeans(beanDefinitions);
184			if (primaryBeans.size() == 1) {
185				return ConditionOutcome.match(spec.message(matchMessage)
186					.found("a single primary bean '" + primaryBeans.get(0) + "' from beans")
187					.items(Style.QUOTE, allBeans));
188			}
189			if (primaryBeans.size() > 1) {
190				return ConditionOutcome
191					.noMatch(spec.message().found("multiple primary beans").items(Style.QUOTE, primaryBeans));
192			}
193			List<String> nonFallbackBeans = getNonFallbackBeans(beanDefinitions);
194			if (nonFallbackBeans.size() == 1) {
195				return ConditionOutcome.match(spec.message(matchMessage)
196					.found("a single non-fallback bean '" + nonFallbackBeans.get(0) + "' from beans")
197					.items(Style.QUOTE, allBeans));
198			}
199			return ConditionOutcome.noMatch(spec.message().found("multiple beans").items(Style.QUOTE, allBeans));
200		}

200		}
