212		protected final MatchResult getMatchingBeans(Spec<?> spec) {
213			ConfigurableListableBeanFactory beanFactory = getSearchBeanFactory(spec);
214			ClassLoader classLoader = spec.getContext().getClassLoader();
215			boolean considerHierarchy = spec.getStrategy() != SearchStrategy.CURRENT;
216			Set<BeanType> parameterizedContainers = spec.getParameterizedContainers();
217			MatchResult result = new MatchResult();
218			Set<String> beansIgnoredByType = getNamesOfBeansIgnoredByType(beanFactory, considerHierarchy,
219					spec.getIgnoredTypes(), parameterizedContainers);
220			for (BeanType type : spec.getTypes()) {
221				Map<String, @Nullable BeanDefinition> typeMatchedDefinitions = getBeanDefinitionsForType(beanFactory,
222						considerHierarchy, type, parameterizedContainers);
223				Set<String> typeMatchedNames = matchedNamesFrom(typeMatchedDefinitions,
224						(name, definition) -> !ScopedProxyUtils.isScopedTarget(name)
225								&& isCandidate(beanFactory, name, definition, beansIgnoredByType));
226				if (typeMatchedNames.isEmpty()) {
227					result.recordUnmatchedType(type);
228				}
229				else {
230					result.recordMatchedType(type, typeMatchedNames);
231				}
232			}
233			for (String annotation : spec.getAnnotations()) {
234				Map<String, @Nullable BeanDefinition> annotationMatchedDefinitions = getBeanDefinitionsForAnnotation(
235						classLoader, beanFactory, annotation, considerHierarchy);
236				Set<String> annotationMatchedNames = matchedNamesFrom(annotationMatchedDefinitions,
237						(name, definition) -> isCandidate(beanFactory, name, definition, beansIgnoredByType));
238				if (annotationMatchedNames.isEmpty()) {
239					result.recordUnmatchedAnnotation(annotation);
240				}
241				else {
242					result.recordMatchedAnnotation(annotation, annotationMatchedNames);
243	
244				}
245			}
246			for (String beanName : spec.getNames()) {
247				if (!beansIgnoredByType.contains(beanName) && containsBean(beanFactory, beanName, considerHierarchy)) {
248					result.recordMatchedName(beanName);
249				}
250				else {
251					result.recordUnmatchedName(beanName);
252				}
253			}
254			return result;
255		}
