257		private ConfigurableListableBeanFactory getSearchBeanFactory(Spec<?> spec) {
258			ConfigurableListableBeanFactory beanFactory = spec.getContext().getBeanFactory();
259			Assert.state(beanFactory != null, "'beanFactory' must not be null'");
260			if (spec.getStrategy() == SearchStrategy.ANCESTORS) {
261				BeanFactory parent = beanFactory.getParentBeanFactory();
262				Assert.state(parent instanceof ConfigurableListableBeanFactory,
263						"Unable to use SearchStrategy.ANCESTORS without ConfigurableListableBeanFactory");
264				beanFactory = (ConfigurableListableBeanFactory) parent;
265			}
266			return beanFactory;
267		}
