269		private Set<String> matchedNamesFrom(Map<String, @Nullable BeanDefinition> namedDefinitions,
270				BiPredicate<String, BeanDefinition> filter) {
271			Set<String> matchedNames = new LinkedHashSet<>(namedDefinitions.size());
272			for (Entry<String, BeanDefinition> namedDefinition : namedDefinitions.entrySet()) {
273				if (filter.test(namedDefinition.getKey(), namedDefinition.getValue())) {
274					matchedNames.add(namedDefinition.getKey());
275				}
276			}
277			return matchedNames;
278		}
