280		private boolean isCandidate(ConfigurableListableBeanFactory beanFactory, String name,
281				@Nullable BeanDefinition definition, Set<String> ignoredBeans) {
282			if (ignoredBeans.contains(name)) {
283				return false;
284			}
285			if (definition == null || (definition.isAutowireCandidate() && isDefaultCandidate(definition))) {
286				return true;
287			}
288			if (ScopedProxyUtils.isScopedTarget(name)) {
289				try {
290					BeanDefinition originalDefinition = beanFactory
291						.getBeanDefinition(ScopedProxyUtils.getOriginalBeanName(name));
292					if (originalDefinition.isAutowireCandidate() && isDefaultCandidate(originalDefinition)) {
293						return true;
294					}
295				}
296				catch (NoSuchBeanDefinitionException ex) {
297				}
298			}
299			return false;
300		}
