302		private boolean isDefaultCandidate(BeanDefinition definition) {
303			if (definition instanceof AbstractBeanDefinition abstractBeanDefinition) {
304				return abstractBeanDefinition.isDefaultCandidate();
305			}
306			return true;
307		}
