309		private Set<String> getNamesOfBeansIgnoredByType(ListableBeanFactory beanFactory, boolean considerHierarchy,
310				Set<BeanType> ignoredTypes, Set<BeanType> parameterizedContainers) {
311			Set<String> result = null;
312			for (BeanType ignoredType : ignoredTypes) {
313				Collection<String> ignoredNames = getBeanDefinitionsForType(beanFactory, considerHierarchy, ignoredType,
314						parameterizedContainers)
315					.keySet();
316				result = addAll(result, ignoredNames);
317			}
318			return (result != null) ? result : Collections.emptySet();
319		}
