321		private Map<String, @Nullable BeanDefinition> getBeanDefinitionsForType(ListableBeanFactory beanFactory,
322				boolean considerHierarchy, BeanType type, Set<BeanType> parameterizedContainers) {
323			Map<String, @Nullable BeanDefinition> result = collectBeanDefinitionsForType(beanFactory, considerHierarchy,
324					type, parameterizedContainers, null);
325			return (result != null) ? result : Collections.<String, @Nullable BeanDefinition>emptyMap();
326		}
