352				ConfigurableListableBeanFactory beanFactory, String type, boolean considerHierarchy) throws LinkageError {
353			Map<String, @Nullable BeanDefinition> result = null;
354			try {
355				result = collectBeanDefinitionsForAnnotation(beanFactory, resolveAnnotationType(classLoader, type),
356						considerHierarchy, result);
357			}
358			catch (ClassNotFoundException ex) {
359				// Continue
360			}
361			return (result != null) ? result : Collections.<String, @Nullable BeanDefinition>emptyMap();
362		}
