370		private @Nullable Map<String, @Nullable BeanDefinition> collectBeanDefinitionsForAnnotation(
371				ListableBeanFactory beanFactory, Class<? extends Annotation> annotationType, boolean considerHierarchy,
372				@Nullable Map<String, @Nullable BeanDefinition> result) {
373			result = putAll(result, getBeanNamesForAnnotation(beanFactory, annotationType), beanFactory);
374			if (considerHierarchy) {
375				BeanFactory parent = ((HierarchicalBeanFactory) beanFactory).getParentBeanFactory();
376				if (parent instanceof ListableBeanFactory listableBeanFactory) {
377					result = collectBeanDefinitionsForAnnotation(listableBeanFactory, annotationType, considerHierarchy,
378							result);
379				}
380			}
381			return result;
382		}
