384		private String[] getBeanNamesForAnnotation(ListableBeanFactory beanFactory,
385				Class<? extends Annotation> annotationType) {
386			Set<String> foundBeanNames = new LinkedHashSet<>();
387			for (String beanName : beanFactory.getBeanDefinitionNames()) {
388				if (beanFactory instanceof ConfigurableListableBeanFactory configurableListableBeanFactory) {
389					BeanDefinition beanDefinition = configurableListableBeanFactory.getBeanDefinition(beanName);
390					if (beanDefinition != null && beanDefinition.isAbstract()) {
391						continue;
392					}
393				}
394				if (beanFactory.findAnnotationOnBean(beanName, annotationType, false) != null) {
395					foundBeanNames.add(beanName);
396				}
397			}
398			if (beanFactory instanceof SingletonBeanRegistry singletonBeanRegistry) {
399				for (String beanName : singletonBeanRegistry.getSingletonNames()) {
400					if (beanFactory.findAnnotationOnBean(beanName, annotationType) != null) {
401						foundBeanNames.add(beanName);
402					}
403				}
404			}
405			return foundBeanNames.toArray(String[]::new);
406		}
