44	public final class StandardStackTracePrinter implements StackTracePrinter {
45	
46		private static final String DEFAULT_LINE_SEPARATOR = System.lineSeparator();
47	
48		private static final ToIntFunction<StackTraceElement> DEFAULT_FRAME_HASHER = (frame) -> Objects
