58	
59		private final Predicate<Throwable> filter;
60	
61		private final BiPredicate<Integer, StackTraceElement> frameFilter;
62	
63		private final Function<Throwable, String> formatter;
64	
65		private final Function<StackTraceElement, String> frameFormatter;
66	
67		private final @Nullable ToIntFunction<StackTraceElement> frameHasher;
