69		private StandardStackTracePrinter(EnumSet<Option> options, int maximumLength, @Nullable String lineSeparator,
70				@Nullable Predicate<Throwable> filter, @Nullable BiPredicate<Integer, StackTraceElement> frameFilter,
71				@Nullable Function<Throwable, String> formatter,
72				@Nullable Function<StackTraceElement, String> frameFormatter,
73				@Nullable ToIntFunction<StackTraceElement> frameHasher) {
74			this.options = options;
75			this.maximumLength = maximumLength;
76			this.lineSeparator = (lineSeparator != null) ? lineSeparator : DEFAULT_LINE_SEPARATOR;
77			this.filter = (filter != null) ? filter : (t) -> true;
78			this.frameFilter = (frameFilter != null) ? frameFilter : (i, t) -> true;
79			this.formatter = (formatter != null) ? formatter : Object::toString;
80			this.frameFormatter = (frameFormatter != null) ? frameFormatter : Object::toString;
81			this.frameHasher = frameHasher;
82		}
