33	/**
34	 * Utility class for converting one type of {@link Environment} to another.
35	 *
36	 * @author Ethan Rubinson
37	 * @author Andy Wilkinson
38	 * @author Madhura Bhave
39	 */
40	final class EnvironmentConverter {
41	
42		private static final String CONFIGURABLE_WEB_ENVIRONMENT_CLASS = "org.springframework.web.context.ConfigurableWebEnvironment";
43	
44		private static final Set<String> SERVLET_ENVIRONMENT_SOURCE_NAMES;
45	
46		static {
47			Set<String> names = new HashSet<>();
48			names.add(StandardServletEnvironment.SERVLET_CONTEXT_PROPERTY_SOURCE_NAME);
49			names.add(StandardServletEnvironment.SERVLET_CONFIG_PROPERTY_SOURCE_NAME);
50			names.add(StandardServletEnvironment.JNDI_PROPERTY_SOURCE_NAME);
51			SERVLET_ENVIRONMENT_SOURCE_NAMES = Collections.unmodifiableSet(names);
52		}
53	
54		private final ClassLoader classLoader;
55	
56		/**
57		 * Creates a new {@link EnvironmentConverter} that will use the given
58		 * {@code classLoader} during conversion.
59		 * @param classLoader the class loader to use
60		 */
61		EnvironmentConverter(ClassLoader classLoader) {
62			this.classLoader = classLoader;
63		}
64	
65		/**
66		 * Converts the given {@code environment} to the given {@link StandardEnvironment}
67		 * type. If the environment is already of the same type, no conversion is performed
68		 * and it is returned unchanged.
69		 * @param environment the Environment to convert
70		 * @param type the type to convert the Environment to
71		 * @return the converted Environment
72		 */
73		ConfigurableEnvironment convertEnvironmentIfNecessary(ConfigurableEnvironment environment,
74				Class<? extends ConfigurableEnvironment> type) {
75			if (type.equals(environment.getClass())) {
76				return environment;
77			}
78			return convertEnvironment(environment, type);
79		}
80	
81		private ConfigurableEnvironment convertEnvironment(ConfigurableEnvironment environment,
82				Class<? extends ConfigurableEnvironment> type) {
83			ConfigurableEnvironment result = createEnvironment(type);
84			result.setActiveProfiles(environment.getActiveProfiles());
85			result.setConversionService(environment.getConversionService());
86			copyPropertySources(environment, result);
87			return result;
88		}
89	
90		private ConfigurableEnvironment createEnvironment(Class<? extends ConfigurableEnvironment> type) {
91			try {
92				Constructor<? extends ConfigurableEnvironment> constructor = type.getDeclaredConstructor();
93				ReflectionUtils.makeAccessible(constructor);
94				return constructor.newInstance();
95			}
96			catch (Exception ex) {
97				return new ApplicationEnvironment();
98			}
99		}
100	
101		private void copyPropertySources(ConfigurableEnvironment source, ConfigurableEnvironment target) {
102			removePropertySources(target.getPropertySources(), isServletEnvironment(target.getClass(), this.classLoader));
103			for (PropertySource<?> propertySource : source.getPropertySources()) {
104				if (!SERVLET_ENVIRONMENT_SOURCE_NAMES.contains(propertySource.getName())) {
105					target.getPropertySources().addLast(propertySource);
106				}
107			}
108		}
109	
110		private boolean isServletEnvironment(Class<?> conversionType, ClassLoader classLoader) {
111			try {
112				Class<?> webEnvironmentClass = ClassUtils.forName(CONFIGURABLE_WEB_ENVIRONMENT_CLASS, classLoader);
113				return webEnvironmentClass.isAssignableFrom(conversionType);
114			}
115			catch (Throwable ex) {
116				return false;
117			}
118		}
119	
120		private void removePropertySources(MutablePropertySources propertySources, boolean isServletEnvironment) {
121			Set<String> names = new HashSet<>();
122			for (PropertySource<?> propertySource : propertySources) {
123				names.add(propertySource.getName());
124			}
125			for (String name : names) {
126				if (!isServletEnvironment || !SERVLET_ENVIRONMENT_SOURCE_NAMES.contains(name)) {
127					propertySources.remove(name);
128				}
129			}
130		}
131	
132	}
