58	final class BindConverter {
59	
60		private static @Nullable BindConverter sharedInstance;
61	
62		private final List<ConversionService> delegates;
63	
64		private BindConverter(@Nullable List<ConversionService> conversionServices,
65				@Nullable Consumer<PropertyEditorRegistry> propertyEditorInitializer) {
66			List<ConversionService> delegates = new ArrayList<>();
67			delegates.add(new TypeConverterConversionService(propertyEditorInitializer));
68			boolean hasApplication = false;
69			if (!CollectionUtils.isEmpty(conversionServices)) {
70				for (ConversionService conversionService : conversionServices) {
71					delegates.add(conversionService);
72					hasApplication = hasApplication || conversionService instanceof ApplicationConversionService;
73				}
74			}
75			if (!hasApplication) {
76				delegates.add(ApplicationConversionService.getSharedInstance());
77			}
78			this.delegates = Collections.unmodifiableList(delegates);
79		}
80	
81		boolean canConvert(@Nullable Object source, ResolvableType targetType, Annotation... targetAnnotations) {
82			return canConvert(TypeDescriptor.forObject(source),
83					new ResolvableTypeDescriptor(targetType, targetAnnotations));
84		}
85	
86		private boolean canConvert(@Nullable TypeDescriptor sourceType, TypeDescriptor targetType) {
87			for (ConversionService service : this.delegates) {
88				if (service.canConvert(sourceType, targetType)) {
89					return true;
90				}
91			}
92			return false;
93		}
94	
95		<T> @Nullable T convert(@Nullable Object source, Bindable<T> target) {
96			return convert(source, target.getType(), target.getAnnotations());
97		}
98	
99		@SuppressWarnings("unchecked")
100		<T> @Nullable T convert(@Nullable Object source, ResolvableType targetType, Annotation... targetAnnotations) {
101			TypeDescriptor sourceType = (source != null) ? TypeDescriptor.forObject(source) : null;
102			return (T) convert(source, sourceType, new ResolvableTypeDescriptor(targetType, targetAnnotations));
103		}
104	
105		private @Nullable Object convert(@Nullable Object source, @Nullable TypeDescriptor sourceType,
106				TypeDescriptor targetType) {
107			ConversionException failure = null;
108			for (ConversionService delegate : this.delegates) {
109				try {
110					if (delegate.canConvert(sourceType, targetType)) {
111						return delegate.convert(source, sourceType, targetType);
112					}
113				}
114				catch (ConversionException ex) {
115					if (failure == null && ex instanceof ConversionFailedException) {
116						failure = ex;
117					}
118				}
119			}
120			if (source == null) {
121				return null;
122			}
123			throw (failure != null) ? failure : new ConverterNotFoundException(sourceType, targetType);
124		}
125	
126		static BindConverter get(@Nullable List<ConversionService> conversionServices,
127				@Nullable Consumer<PropertyEditorRegistry> propertyEditorInitializer) {
128			boolean sharedApplicationConversionService = (conversionServices == null) || (conversionServices.size() == 1
129					&& conversionServices.get(0) == ApplicationConversionService.getSharedInstance());
130			if (propertyEditorInitializer == null && sharedApplicationConversionService) {
131				return getSharedInstance();
132			}
133			return new BindConverter(conversionServices, propertyEditorInitializer);
134		}
135	
136		private static BindConverter getSharedInstance() {
137			if (sharedInstance == null) {
138				sharedInstance = new BindConverter(null, null);
139			}
140			return sharedInstance;
141		}
