120			this.file = file;
121		}
122	
123		/**
124		 * Sets the type of application event that will trigger writing of the PID file.
125		 * Defaults to {@link ApplicationPreparedEvent}. NOTE: If you use the
126		 * {@link org.springframework.boot.context.event.ApplicationStartingEvent} to trigger
127		 * the write, you will not be able to specify the PID filename in the Spring
128		 * {@link Environment}.
129		 * @param triggerEventType the trigger event type
130		 */
131		public void setTriggerEventType(Class<? extends SpringApplicationEvent> triggerEventType) {
132			Assert.notNull(triggerEventType, "'triggerEventType' must not be null");
133			this.triggerEventType = triggerEventType;
134		}
135	
136		@Override
137		public void onApplicationEvent(SpringApplicationEvent event) {
138			if (this.triggerEventType.isInstance(event) && created.compareAndSet(false, true)) {
139				try {
140					writePidFile(event);
141				}
142				catch (Exception ex) {
143					String message = String.format("Cannot create pid file %s", this.file);
144					if (failOnWriteError(event)) {
145						throw new IllegalStateException(message, ex);
146					}
147					logger.warn(message, ex);
148				}
149			}
150		}
151	
152		private void writePidFile(SpringApplicationEvent event) throws IOException {
153			File pidFile = this.file;
154			String override = getProperty(event, FILE_PROPERTIES);
155			if (override != null) {
156				pidFile = new File(override);
157			}
158			new ApplicationPid().write(pidFile);
159			pidFile.deleteOnExit();
160		}
161	
162		private boolean failOnWriteError(SpringApplicationEvent event) {
163			String value = getProperty(event, FAIL_ON_WRITE_ERROR_PROPERTIES);
164			return Boolean.parseBoolean(value);
165		}
166	
167		private @Nullable String getProperty(SpringApplicationEvent event, List<Property> candidates) {
168			for (Property candidate : candidates) {
169				String value = candidate.getValue(event);
170				if (value != null) {
171					return value;
172				}
173			}
174			return null;
175		}
