202		/**
203		 * {@link Property} obtained from Spring's {@link Environment}.
204		 */
205		private static class SpringProperty implements Property {
206	
207			private final String prefix;
208	
209			private final String key;
210	
211			SpringProperty(String prefix, String key) {
212				this.prefix = prefix;
213				this.key = key;
214			}
215	
216			@Override
217			public @Nullable String getValue(SpringApplicationEvent event) {
218				Environment environment = getEnvironment(event);
219				if (environment == null) {
220					return null;
221				}
222				return environment.getProperty(this.prefix + this.key);
223			}
224	
225			private @Nullable Environment getEnvironment(SpringApplicationEvent event) {
226				if (event instanceof ApplicationEnvironmentPreparedEvent environmentPreparedEvent) {
227					return environmentPreparedEvent.getEnvironment();
228				}
229				if (event instanceof ApplicationPreparedEvent preparedEvent) {
230					return preparedEvent.getApplicationContext().getEnvironment();
231				}
232				if (event instanceof ApplicationReadyEvent readyEvent) {
233					return readyEvent.getApplicationContext().getEnvironment();
234				}
235				return null;
236			}
237	
238		}
