430	
431			public @Nullable Collection<?> applyTo(@Nullable Collection<?> items) {
432				if (items == null) {
433					return null;
434				}
435				List<Object> result = new ArrayList<>(items.size());
436				for (Object item : items) {
437					Object applied = applyToItem(item);
438					if (applied != null) {
439						result.add(applied);
440					}
441				}
442				return result;
443			}
444	
445			protected abstract @Nullable Object applyToItem(@Nullable Object item);
