62		@Override
63		public <T> @Nullable T bind(ConfigurationPropertyName name, Bindable<T> target, Context context,
64				DataObjectPropertyBinder propertyBinder, boolean fallbackToDefaultValue) {
65			boolean hasKnownBindableProperties = target.getValue() != null && hasKnownBindableProperties(name, context);
66			Bean<T> bean = Bean.get(target, context, hasKnownBindableProperties);
67			if (bean == null) {
68				return null;
69			}
70			BeanSupplier<T> beanSupplier = bean.getSupplier(target);
71			boolean bound = bind(propertyBinder, bean, beanSupplier, context);
72			return (bound ? beanSupplier.get() : null);
73		}
74	
75		@Override
76		@SuppressWarnings("unchecked")
77		public <T> @Nullable T create(Bindable<T> target, Context context) {
78			Class<T> type = (Class<T>) target.getType().resolve();
79			return (type != null) ? BeanUtils.instantiateClass(type) : null;
80		}
81	
82		private boolean hasKnownBindableProperties(ConfigurationPropertyName name, Context context) {
83			Map<ConfigurationPropertyName, Boolean> cache = getHasKnownBindablePropertiesCache(context);
84			Boolean hasKnownBindableProperties = cache.get(name);
85			if (hasKnownBindableProperties == null) {
86				hasKnownBindableProperties = computeHasKnownBindableProperties(name, context);
87				cache.put(name, hasKnownBindableProperties);
88			}
89			return hasKnownBindableProperties;
90		}
91	
92		private boolean computeHasKnownBindableProperties(ConfigurationPropertyName name, Context context) {
93			for (ConfigurationPropertySource source : context.getSources()) {
94				if (source.containsDescendantOf(name) == ConfigurationPropertyState.PRESENT) {
95					return true;
96				}
97			}
98			return false;
99		}
100	
101		@SuppressWarnings("unchecked")
102		private Map<ConfigurationPropertyName, Boolean> getHasKnownBindablePropertiesCache(Context context) {
103			Object cache = context.getCache().get(HAS_KNOWN_BINDABLE_PROPERTIES_CACHE);
104			if (cache == null) {
105				cache = new ConcurrentHashMap<ConfigurationPropertyName, Boolean>();
106				context.getCache().put(HAS_KNOWN_BINDABLE_PROPERTIES_CACHE, cache);
107			}
108			return (Map<ConfigurationPropertyName, Boolean>) cache;
109		}
110	
111		private <T> boolean bind(DataObjectPropertyBinder propertyBinder, Bean<T> bean, BeanSupplier<T> beanSupplier,
112				Context context) {
113			boolean bound = false;
114			for (BeanProperty beanProperty : bean.getProperties().values()) {
115				bound |= bind(beanSupplier, propertyBinder, beanProperty);
116				context.clearConfigurationProperty();
117			}
118			return bound;
119		}
120	
121		private <T> boolean bind(BeanSupplier<T> beanSupplier, DataObjectPropertyBinder propertyBinder,
122				BeanProperty property) {
123			String propertyName = determinePropertyName(property);
124			ResolvableType type = property.getType();
125			Supplier<Object> value = property.getValue(beanSupplier);
126			Annotation[] annotations = property.getAnnotations();
127			Object bound = propertyBinder.bindProperty(propertyName,
128					Bindable.of(type).withSuppliedValue(value).withAnnotations(annotations));
129			if (bound == null) {
130				return false;
131			}
132			if (property.isSettable()) {
133				property.setValue(beanSupplier, bound);
134			}
135			else if (value == null || !bound.equals(value.get())) {
136				throw new IllegalStateException("No setter found for property: " + property.getName());
137			}
138			return true;
139		}
140	
141		private String determinePropertyName(BeanProperty property) {
142			return Arrays.stream((property.getAnnotations() != null) ? property.getAnnotations() : new Annotation[0])
143				.filter((annotation) -> annotation.annotationType() == Name.class)
144				.findFirst()
145				.map(Name.class::cast)
146				.map(Name::value)
147				.orElse(property.getName());
148		}
