329				ListableBeanFactory beanFactory, boolean considerHierarchy, BeanType type,
330				Set<BeanType> parameterizedContainers, @Nullable Map<String, @Nullable BeanDefinition> result) {
331			if (ResolvableType.NONE.equals(type.resolvableType())) {
332				return result;
333			}
334			result = putAll(result, beanFactory.getBeanNamesForType(type.resolvableType(), true, false), beanFactory);
335			for (BeanType parameterizedContainer : parameterizedContainers) {
336				Class<?> resolved = parameterizedContainer.resolvableType().resolve();
337				Assert.state(resolved != null, "'resolved' must not be null");
338				ResolvableType generic = ResolvableType.forClassWithGenerics(resolved, type.resolvableType());
339				result = putAll(result, beanFactory.getBeanNamesForType(generic, true, false), beanFactory);
340			}
341			if (considerHierarchy && beanFactory instanceof HierarchicalBeanFactory hierarchicalBeanFactory) {
